CREATE TABLE customers(id varchar(100) PRIMARY KEY,display_name varchar(255) NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('ACTIVE','CLOSED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(100) PRIMARY KEY,customer_id varchar(100) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),status varchar(16) NOT NULL DEFAULT 'ACTIVE' CHECK(status IN('ACTIVE','FROZEN','CLOSED')),can_receive boolean NOT NULL DEFAULT true,max_transfer numeric(19,3) NOT NULL DEFAULT 10000 CHECK(max_transfer>0),version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_debit_grants(account_id varchar(100) REFERENCES accounts(id) ON DELETE RESTRICT,subject varchar(255) NOT NULL,PRIMARY KEY(account_id,subject));
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(100) NOT NULL,to_account_id varchar(100) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL DEFAULT 'JOD' CHECK(currency='JOD'),instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000),payload_fingerprint char(64) NOT NULL,status varchar(16) NOT NULL CHECK(status IN('PROCESSING','COMPLETED','REJECTED')),rejection_code varchar(64),rejection_http integer,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,requested_by varchar(255) NOT NULL,correlation_id varchar(100) NOT NULL,CHECK(from_account_id<>to_account_id));
CREATE INDEX payments_from_date ON payments(from_account_id,created_at);
CREATE INDEX payments_to_date ON payments(to_account_id,created_at);
CREATE INDEX payments_requested_date ON payments(requested_by,created_at);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(100) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(6) NOT NULL CHECK(entry_type IN('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR (entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account_date ON ledger_entries(account_id,id);
CREATE FUNCTION financial_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Financial record is immutable' USING ERRCODE='23514'; END $$;
CREATE TRIGGER ledger_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION financial_immutable();
CREATE FUNCTION payment_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status<>'PROCESSING' THEN RAISE EXCEPTION 'Payment is immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER payments_immutable BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION payment_immutable();
CREATE FUNCTION opening_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.opening_balance<>OLD.opening_balance THEN RAISE EXCEPTION 'Opening balance is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER accounts_opening_immutable BEFORE UPDATE ON accounts FOR EACH ROW EXECUTE FUNCTION opening_immutable();
CREATE FUNCTION validate_payment_ledger() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p payments%ROWTYPE; n integer; total numeric; matching integer;
BEGIN SELECT * INTO p FROM payments WHERE payment_id=NEW.payment_id;
 SELECT count(*),coalesce(sum(signed_amount),0),count(*) FILTER(WHERE (entry_type='DEBIT' AND account_id=p.from_account_id AND signed_amount=-p.amount) OR (entry_type='CREDIT' AND account_id=p.to_account_id AND signed_amount=p.amount)) INTO n,total,matching FROM ledger_entries WHERE payment_id=p.payment_id;
 IF p.status='PROCESSING' OR (p.status='COMPLETED' AND (n<>2 OR total<>0 OR matching<>2)) OR (p.status='REJECTED' AND n<>0) THEN RAISE EXCEPTION 'Unbalanced or unfinished payment' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER payment_balanced AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_payment_ledger();
CREATE CONSTRAINT TRIGGER ledger_balanced AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_payment_ledger();
COMMENT ON COLUMN payments.from_account_id IS 'Instruction identity; no FK so rejected nonexistent accounts can be recorded. Completed account references enforced by ledger FKs and deferred consistency trigger.';
